// ARYA UI Translation System
// 25 languages: 12 Indian + 13 International
// Every string uses ARYA's warm, friend-like register — not formal/corporate.
// RTL support built in: Arabic, Hebrew.
// Fallback: always English if a key is missing.

export type UiLanguage =
  // Indian
  | "en" | "hi" | "mr" | "bn" | "ta" | "te" | "kn" | "ml" | "gu" | "pa" | "od" | "sa"
  // International
  | "ar" | "he" | "fr" | "es" | "de" | "ja" | "zh" | "ko" | "pt" | "ru" | "tr" | "id" | "sw";

export const RTL_LANGUAGES: Set<UiLanguage> = new Set(["ar", "he"]);

export function isRTLLanguage(lang: UiLanguage): boolean {
  return RTL_LANGUAGES.has(lang);
}

